silhouette effuse.feed:
// 1. where this pixel takes its light from: toward the body's edge, toward the joints, through the churn
//    (taking from nearer the body is what moves the light outward)
vec2 g = maskGrad(uv, effuse_reach);
float gl = length(g);
vec2 p = uv;
if (gl > 0.001) p += g / gl * effuse * min(1.0, gl * 2.0);
p += wells(uv, emit, emit_reach, emit_base, emit_speed);
vec2 q = vec2(uv.x / aspect, uv.y);
p += curl(q * churn_size, time * churn_speed) * churn * 0.004;
// 2. the marbling: each colour is fetched a little along the light's own gradient, so it folds into veins, not a glow
vec2 px = vec2(marble / res.x, marble / res.y);
vec3 gx = frameSoft(uv + vec2(px.x, 0.0)) - frameSoft(uv - vec2(px.x, 0.0));
vec3 gy = frameSoft(uv + vec2(0.0, px.y)) - frameSoft(uv - vec2(0.0, px.y));
vec3 old = vec3(frame(p + vec2(gx.r, gy.r) * px).r, frame(p + vec2(gx.g, gy.g) * px).g, frame(p + vec2(gx.b, gy.b) * px).b);
old -= (old - frameBlur(p)) * 0.02;
// 3. aged: its colour drifts, it decays, it dies beyond reach from the body
old = mix(old, old.yzx, rotate) * decay;
old *= mix(fade, 1.0, maskNear(uv, reach));
// 4. the boil: cells born on the body, a different pattern in each colour, so the veins carry different hues.
//    The cells are placed relative to the torso and sized by the body's size on screen (tf_size: the torso
//    height, which holds steady when the person turns), so they travel with the body and keep their size
//    as it comes nearer; a screen-fixed pattern under a moving mask is not emission.
vec2 anchor = vec2(tf_torso_x, tf_torso_y);
float sw = max(0.05, tf_size);
vec2 bq = (vec2(uv.x / aspect, uv.y) - vec2(anchor.x / aspect, anchor.y)) / sw;
vec3 c3 = vec3(bq * churn_size * 0.6, time * churn_speed);
vec3 cells = vec3(noise3(c3), noise3(c3 + 17.3), noise3(c3 + 41.7)) * 0.65 + vec3(noise3(c3 * 2.2 + 3.1), noise3(c3 * 2.2 + 23.9), noise3(c3 * 2.2 + 57.2)) * 0.35;
old += (cells - 0.5) * boil * mask(uv);
// the picture painted in: the person's own video mixed into the light inside the mask; 0 = pure coloured light
ret = mix(old, cutout(uv), mask(uv) * inject);

silhouette effuse.show:
vec3 raw = frame(uv), soft = frameBlur(uv), fine = frameSoft(uv);
float l = lum(soft);
// the hue: from the light's age (the channel drift), a slow cycle, inside hue_min..hue_max
float age = (soft.r - soft.b) + (soft.g - soft.r) * 0.7;
float t = fract(0.5 + time * hue_rate + age * hue_age);
t = t < 0.5 ? t * 2.0 : 2.0 - t * 2.0;
vec3 col = hsv(mix(hue_min, hue_max, t), saturation, 1.0);
// the brightness: between the two levels inside the body, fading to black outside it
float inside = mask(uv);
float b = level_min + (level_max - level_min) * pow(clamp(l * gain, 0.0, 1.0), 0.75);
b = mix(clamp(l * gain * 2.0, 0.0, 1.0) * level_max, b, inside);
// the seeds: what is sharper than its surroundings
float seed = lum(clamp(raw - fine, 0.0, 1.0));
ret = col * (b + seed * seed_gain);
// colour punch: 1 = as computed, higher = richer, 0 = grey
// the picture painted in: the frame's TRUE colours (the injected video and its effused copies)
// shown in place of the palette by the same dial; 0 = palette only
ret = mix(ret, raw * gain, clamp(inject * 1.2, 0.0, 1.0));
ret = mix(vec3(lum(ret)), ret, punch);
// fully opaque: the Stage tab's Effect opacity alone decides how much video shows through
alpha = 1.0;

video effuse.feed:
// where this pixel takes its light from: toward the body's edge, toward the joints, through the churn
vec2 g = maskGrad(uv, effuse_reach);
float gl = length(g);
vec2 p = uv;
if (gl > 0.001) p += g / gl * effuse * min(1.0, gl * 2.0);
p += wells(uv, emit, emit_reach, emit_base, emit_speed);
vec2 q = vec2(uv.x / aspect, uv.y);
p += curl(q * churn_size, time * churn_speed) * churn * 0.004;
// the marbling: each colour carried a little along the light's own gradient, so the picture folds into veins
vec2 px = vec2(marble / res.x, marble / res.y);
vec3 gx = frameSoft(uv + vec2(px.x, 0.0)) - frameSoft(uv - vec2(px.x, 0.0));
vec3 gy = frameSoft(uv + vec2(0.0, px.y)) - frameSoft(uv - vec2(0.0, px.y));
vec3 old = vec3(frame(p + vec2(gx.r, gy.r) * px).r, frame(p + vec2(gx.g, gy.g) * px).g, frame(p + vec2(gx.b, gy.b) * px).b);
// aged: optional colour drift, decay, death beyond reach from the body
old = mix(old, old.yzx, rotate) * decay;
old *= mix(fade, 1.0, maskNear(uv, reach));
// the source is the person's own picture, taken through a swirling lens: inside the mask the video's
// pixels roil in place (the boil), and what the lens displaces is scaled by the mask so the edge holds
vec2 wob = curl(q * churn_size * 2.0, time * churn_speed * 1.4) * boil * 0.01 * mask(uv);
vec3 me = cutout(uv + wob);
ret = mix(old, me, mask(uv) * inject);

video effuse.show:
// the video's own colours, lifted a little; the camera sits behind, the matte cuts the room
vec3 t = frame(uv) * gain;
vec3 col = mix(vec3(lum(t)), t, punch);
ret = col;
alpha = 1.0;

outlines.show:
// the live picture (dialled to black by backing), the takes oldest-under-newest, the person now, the edge trail
vec3 live = cam(uv);
vec3 c = live * backing;
vec2 q = vec2(uv.x / aspect, uv.y);
for (int k = 24; k >= 0; k--) {
  if (k >= hist_n) continue;
  vec3 t = hist(k, uv);
  float pres = clamp(lum(t) * 6.0, 0.0, 1.0);            // where this take has content
  float w = exp(-histAge(k) / max(0.05, life));           // CONTINUOUS age in seconds: no steps, no snap
  float n = noise3(vec3(q * grain, float(k) * 7.31));     // a fixed ragged pattern per take
  float gate = mix(1.0, smoothstep(0.0, 0.25, w - n * (1.0 - w)), dissolve);   // eaten along the pattern as it ages
  vec3 col = mix(t, hsv(hue, saturation, 1.0) * lum(t), tint);
  c = mix(c, col, pres * w * gate * takes);
}
c = mix(c, live, mask(uv) * live_solid);
c += frame(uv) * glow;
ret = c;
alpha = 1.0;
